import React from 'react';
import ReactDOM from 'react-dom/client';
import { createBrowserRouter, RouterProvider } from 'react-router-dom';
import Layout from './components/templates/Layout';
const rootElement = document.getElementById('root');
if (rootElement) {
    const router = createBrowserRouter([
        {
            path: `${relativeHomeURL}/`,
            element: React.createElement(Layout, { postType: "landing-page", slug: "home" }),
        },
        {
            path: `${relativeHomeURL}/iframe/:postType/:slug`,
            element: React.createElement(Layout, { iframe: true }),
        },
        {
            path: `${relativeHomeURL}/iframe/:slug`,
            element: React.createElement(Layout, { postType: "landing-page", iframe: true }),
        },
        {
            path: `${relativeHomeURL}/:postType/:slug`,
            element: React.createElement(Layout, null),
        },
        {
            path: `${relativeHomeURL}/:slug`,
            element: React.createElement(Layout, { postType: "landing-page" }),
        },
    ]);
    ReactDOM.createRoot(rootElement).render(React.createElement(RouterProvider, { router: router }));
}
else {
    console.error('Failed to find the root element.');
}
