import React from 'react';
const { useEffect, useState } = wp.element;
import { doGetHeadline } from 'src/utils/api';
import { doLength } from 'src/utils/helpers';
import CTA from 'src/components/shared/CTA';
import 'assets/styles/components/header-promo.scss';
const HeaderPromo = () => {
    // Get the posts
    const [promo, setPromo] = useState([]);
    useEffect(() => {
        async function fetchData() {
            await doGetHeadline().then((data) => {
                setPromo(data.json);
            });
        }
        fetchData();
    }, []);
    if (doLength(promo)) {
        const active = promo.active;
        const headline = promo.headline;
        const url = promo.url;
        const modal = promo.modal;
        if (active && doLength(headline)) {
            return (React.createElement(CTA, { url: url, modal: modal, classes: ['text-button'] }, headline));
        }
        else {
            return null;
        }
    }
    else {
        return null;
    }
};
export default HeaderPromo;
