import { WPAPIEndpoint } from 'src/globalVariables';
const doGetPost = async (postType = '', slug = '', queryString) => {
    try {
        const postEndpoint = `${WPAPIEndpoint}/${postType}?slug=${slug}${queryString ? '&' + queryString : ''}`;
        if (doEnv !== 'prod') {
            console.log('doGetPost ' + postEndpoint);
        }
        const response = await fetch(postEndpoint);
        const json = await response.json();
        const result = {
            totalPages: response.headers.get('x-wp-totalpages'),
            totalPosts: response.headers.get('x-wp-total'),
            allHeaders: response.headers,
            json,
        };
        return result;
    }
    catch (error) {
        console.log('Error fetching post: ' + error);
        throw error;
    }
};
export default doGetPost;
