import { doArrayFind, doArrayMerge } from 'src/utils/helpers';
// Truncates text at the end of a sentence if possible (or always if threshold == false )
const doTruncate = (text = '', settings) => {
    if (!text.length) {
        return '';
    }
    const indicator = settings.indicator || '';
    const indicatorHTML = indicator.length ? `<span class="truncated-indicator">${indicator}</span>` : '';
    const count = settings.count ? settings.count : 25;
    const countType = settings.countType ? settings.countType : 'words';
    const threshold = settings.threshold ? settings.threshold : 5;
    const splitter = countType == 'words' ? ' ' : '';
    const items = text.split(splitter);
    let truncatedText = text;
    if (items.length > count) {
        truncatedText = items.slice(0, count).join(splitter) + indicatorHTML;
        const minThreshold = threshold && count - threshold > 0 ? count - threshold : 0;
        const maxThreshold = threshold && count + threshold < items.length ? count + threshold : items.length;
        const periods = doArrayFind('.', items);
        const exclamationPoints = doArrayFind('!', items);
        const questionMarks = doArrayFind('?', items);
        const punctuation = doArrayMerge(periods, exclamationPoints, questionMarks);
        punctuation.sort(function (a, b) { return a - b; });
        punctuation.forEach((location, index) => {
            // If the sentence end is within the min & max threshold, we're done
            if (location >= minThreshold && location <= maxThreshold) {
                truncatedText = items.slice(0, location + 1).join(splitter) + indicatorHTML;
                return;
            }
            // If the sentence end is below the min threshold, hang onto it in case we need to return it
            else if (location < minThreshold) {
                truncatedText = items.slice(0, location + 1).join(splitter) + indicatorHTML;
            }
        });
    }
    return truncatedText;
};
export default doTruncate;
