import { WPAPIEndpoint } from 'src/globalVariables';
const doSubmitForm = async (queryString = '') => {
    try {
        const formSubmitEndpoint = `${WPAPIEndpoint}/do-form-submit?${queryString}`;
        if (doEnv !== 'prod') {
            console.log('doSubmitForm ' + formSubmitEndpoint);
        }
        const response = await fetch(formSubmitEndpoint);
        const json = await response.json();
        const result = {
            totalPages: response.headers.get('x-wp-totalpages'),
            totalPosts: response.headers.get('x-wp-total'),
            allHeaders: response.headers,
            json,
        };
        return result;
    }
    catch (error) {
        console.log('Error fetching form submit: ' + error);
        throw error;
    }
};
export default doSubmitForm;
