import { WPAPIEndpoint } from 'src/globalVariables';
const doGetNavMenu = async () => {
    try {
        const menusAllEndpoint = `${WPAPIEndpoint}/menu/`;
        if (doEnv !== 'prod') {
            console.log('doGetNavMenu ' + menusAllEndpoint);
        }
        const response = await fetch(menusAllEndpoint);
        const json = response.json();
        const result = {
            totalPages: response.headers.get('x-wp-totalpages'),
            totalPosts: response.headers.get('x-wp-total'),
            allHeaders: response.headers,
            json,
        };
        return result;
    }
    catch (error) {
        console.log('Error fetching nav menus: ' + error);
        throw error;
    }
};
export default doGetNavMenu;
