import { WPAPIEndpoint } from 'src/globalVariables';
const doGetSearch = async (args) => {
    try {
        const queryString = new URLSearchParams(args).toString();
        const searchEndpoint = `${WPAPIEndpoint}/search?postID=${args.postID}&metaPrefix=${args.metaPrefix}&${queryString}`;
        if (doEnv !== 'prod') {
            console.log('doGetSearch ' + searchEndpoint);
        }
        const response = await fetch(searchEndpoint);
        const json = await response.json();
        const result = {
            totalPages: response.headers.get('x-wp-totalpages'),
            totalPosts: response.headers.get('x-wp-total'),
            allHeaders: response.headers,
            json,
        };
        return result;
    }
    catch (error) {
        console.log('Error fetching search: ' + error);
        throw error;
    }
};
export default doGetSearch;
