import { WPAPIEndpoint } from 'src/globalVariables';
const doGetOption = async (optionName = '') => {
    try {
        const optionEndpoint = `${WPAPIEndpoint}/get-option?name=${optionName}`;
        if (doEnv !== 'prod') {
            console.log('doGetOption ' + optionEndpoint);
        }
        const response = await fetch(optionEndpoint);
        const json = await response.json();
        const result = {
            totalPages: response.headers.get('x-wp-totalpages'),
            totalPosts: response.headers.get('x-wp-total'),
            allHeaders: response.headers,
            json,
        };
        return result;
    }
    catch (error) {
        console.log('Error fetching option: ' + error);
        throw error;
    }
};
export default doGetOption;
