import { WPAPIEndpoint } from 'src/globalVariables';
const doGetFooterCTA = async () => {
    try {
        const footerCTAEndpoint = `${WPAPIEndpoint}/footer-cta/`;
        if (doEnv !== 'prod') {
            console.log('doGetFooterCTA ' + footerCTAEndpoint);
        }
        const response = await fetch(footerCTAEndpoint);
        const json = await response.json();
        const result = {
            totalPages: response.headers.get('x-wp-totalpages'),
            totalPosts: response.headers.get('x-wp-total'),
            allHeaders: response.headers,
            json,
        };
        return result;
    }
    catch (error) {
        console.error('Error fetching footer CTA: ', error);
        throw error;
    }
};
export default doGetFooterCTA;
