export const PageSlugContext = createContext('');
const TemplateLoader = ({ iframe = false, postType, queryString = '', slug, layoutClassesFunction }) => {
    const [post, setPost] = useState(undefined);
    const [TemplateName, setTemplateName] = useState();
    let finalPostType = postType;
    if (finalPostType === 'media') {
        // rename
        finalPostType = 'media-library';
    }
    else if (finalPostType === 'page') {
        // rename
        finalPostType = 'simple-page';
    }
    useEffect(() => {
        async function fetchData() {
            await doGetPost(finalPostType, slug, queryString).then((data) => {
                if (data.json) {
                    setPost(data.json);
                    const template = templates[finalPostType] ? templates[finalPostType] : templates.default;
                    setTemplateName(template);
                }
                else {
                    setPost(undefined);
                    setTemplateName(templates['404']);
                }
            });
        }
        fetchData();
    }, [slug]);
    if (TemplateName && post) {
        return (React.createElement(Suspense, { fallback: React.createElement(Loading, null) },
            React.createElement(PageSlugContext.Provider, { value: slug },
                React.createElement(TemplateName, { post: post, iframe: iframe ? iframe : false, layoutClasses: layoutClassesFunction })),
            React.createElement(ScrollRestoration, null)));
    }
    else {
        return null;
    }
};
export default TemplateLoader;
