import { WPAPIEndpoint } from 'src/globalVariables';
const doGetForm = async (formID) => {
    try {
        const formEndpoint = WPAPIEndpoint + '/do-form/?formID=' + formID;
        if (doEnv !== 'prod') {
            console.log('doGetForm ' + formEndpoint);
        }
        const response = await fetch(formEndpoint);
        const json = await response.json();
        const result = {
            totalPages: response.headers.get('x-wp-totalpages'),
            totalPosts: response.headers.get('x-wp-total'),
            allHeaders: response.headers,
            json,
        };
        return result;
    }
    catch (error) {
        console.log(' Error fetching form: ' + error);
        throw error;
    }
};
export default doGetForm;
