import React from 'react';
const { useEffect, useState } = wp.element;
import { doGetFooterCTA } from 'src/utils/api';
import { doLength } from 'src/utils/helpers';
import CTA from 'src/components/shared/CTA';
const FooterCTA = () => {
    // Get the posts
    const [cta, setCTA] = useState({});
    useEffect(() => {
        async function fetchData() {
            await doGetFooterCTA().then((data) => {
                setCTA(data.json);
            });
        }
        fetchData();
    }, []);
    if (doLength(cta)) {
        if (doLength(cta.text)) {
            return (React.createElement(CTA, { url: cta.url, modal: cta.modal, id: "footer-cta", classes: ['solid-button'] }, cta.text));
        }
        else {
            return null;
        }
    }
    else {
        return null;
    }
};
export default FooterCTA;
