const doBackgroundImage = (settings = {}, classes = []) => {
    const allMedia = settings.media;
    const backgroundMedia = allMedia ? allMedia.background : undefined;
    const backgroundOverlay = settings.overlay;
    const backgroundColor = settings.color;
    const backgroundParallax = settings.parallax;
    const backgroundMediaType = settings.media ? settings.media.type : undefined;
    const avatar = settings.avatar;
    const animated = settings.animated;
    if (backgroundOverlay) {
        classes.push('overlay-' + backgroundOverlay);
    }
    if (backgroundMediaType === 'video') {
        classes.push('has-video-controls');
    }
    const styleAttribute = {};
    const outputAttributes = {};
    if (backgroundMediaType === 'image') {
        const imageURL = backgroundMedia ? backgroundMedia.url : undefined;
        const mobileImageDetails = allMedia ? allMedia.background_mobile : undefined;
        const mobileImageURL = mobileImageDetails && mobileImageDetails.url ? mobileImageDetails.url : imageURL;
        styleAttribute['--background-image'] = 'url(' + imageURL + ')';
        styleAttribute['--mobile-background-image'] = 'url(' + mobileImageURL + ')';
    }
    if (backgroundColor) {
        classes.push('color-' + backgroundColor);
    }
    if (avatar && !animated) {
        classes.push('has-avatar');
    }
    if (styleAttribute) {
        outputAttributes.style = styleAttribute;
    }
    if (backgroundParallax) {
        outputAttributes['uk-parallax'] = 'bgy: ' + backgroundParallax;
    }
    if (classes.length) {
        outputAttributes.className = classes.join(' ');
    }
    return outputAttributes;
};
export default doBackgroundImage;
