import { WPAPIEndpoint } from 'src/globalVariables';
const doGetArchivePosts = async (args) => {
    try {
        const queryString = new URLSearchParams(args).toString();
        const archiveAllEndpoint = `${WPAPIEndpoint}/archive/?${queryString}`;
        if (doEnv !== 'prod') {
            console.log('doGetArchivePosts ' + archiveAllEndpoint);
        }
        const response = await fetch(archiveAllEndpoint);
        const json = await response.json();
        const result = {
            totalPages: response.headers.get('x-wp-totalpages'),
            totalPosts: response.headers.get('x-wp-total'),
            allHeaders: response.headers,
            json,
        };
        return result;
    }
    catch (error) {
        console.error('Error fetching archive posts: ', error);
        throw error;
    }
};
export default doGetArchivePosts;
