import { WPAPIEndpoint } from 'src/globalVariables';
const doGetHeadline = async () => {
    try {
        const promoEndpoint = `${WPAPIEndpoint}/promo/`;
        if (doEnv !== 'prod') {
            console.log('doGetHeadline ' + promoEndpoint);
        }
        const response = await fetch(promoEndpoint);
        const json = await response.json();
        const result = {
            totalPages: response.headers.get('x-wp-totalpages'),
            totalPosts: response.headers.get('x-wp-total'),
            allHeaders: response.headers,
            json,
        };
        return result;
    }
    catch (error) {
        console.log('Error fetching headline: ' + error);
        throw error;
    }
};
export default doGetHeadline;
